/**
 * Options for [`ProxyClient::new`]. In production a host passes only
 * `publisherId`; the gateway address and CA are development overrides.
 */
public struct ProxyConfig {
    public var publisherId: String
    public var gatewayAddresses: [String]
    public var caCertPath: String?
    public var caCertPem: Data?
    public var startTimeoutMs: UInt32?
    public var connectTimeoutMs: UInt32?
    /**
     * Stable id for this machine, if the host keeps one. The SDK never mints or
     * stores it — only the host knows where an id belongs on its platform.
     */
    public var deviceId: String?
    /**
     * A human name for this machine, conventionally its hostname.
     */
    public var deviceName: String?
    /**
     * Which binding is calling: "python", "ruby", "go", "swift", "kotlin".
     * Unlike the node binding, this crate cannot detect it — uniffi generates
     * all five from this one crate — so a host that wants its language
     * attributed correctly sets it here. Defaults to the SDK's own default.
     */
    public var sdk: String?
    /**
     * The host application, e.g. "my-app/2.1.0".
     */
    public var app: String?
    /**
     * The transport the host is on at start: "cellular", "wifi", "ethernet"
     * or "other". Report later changes with `set_network`.
     */
    public var network: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(publisherId: String, gatewayAddresses: [String], caCertPath: String? = nil, caCertPem: Data? = nil, startTimeoutMs: UInt32? = nil, connectTimeoutMs: UInt32? = nil, 
        /**
         * Stable id for this machine, if the host keeps one. The SDK never mints or
         * stores it — only the host knows where an id belongs on its platform.
         */deviceId: String? = nil, 
        /**
         * A human name for this machine, conventionally its hostname.
         */deviceName: String? = nil, 
        /**
         * Which binding is calling: "python", "ruby", "go", "swift", "kotlin".
         * Unlike the node binding, this crate cannot detect it — uniffi generates
         * all five from this one crate — so a host that wants its language
         * attributed correctly sets it here. Defaults to the SDK's own default.
         */sdk: String? = nil, 
        /**
         * The host application, e.g. "my-app/2.1.0".
         */app: String? = nil, 
        /**
         * The transport the host is on at start: "cellular", "wifi", "ethernet"
         * or "other". Report later changes with `set_network`.
         */network: String? = nil) {
        self.publisherId = publisherId
        self.gatewayAddresses = gatewayAddresses
        self.caCertPath = caCertPath
        self.caCertPem = caCertPem
        self.startTimeoutMs = startTimeoutMs
        self.connectTimeoutMs = connectTimeoutMs
        self.deviceId = deviceId
        self.deviceName = deviceName
        self.sdk = sdk
        self.app = app
        self.network = network
    }
}



extension ProxyConfig: Equatable, Hashable {
    public static func ==(lhs: ProxyConfig, rhs: ProxyConfig) -> Bool {
        if lhs.publisherId != rhs.publisherId {
            return false
        }
        if lhs.gatewayAddresses != rhs.gatewayAddresses {
            return false
        }
        if lhs.caCertPath != rhs.caCertPath {
            return false
        }
        if lhs.caCertPem != rhs.caCertPem {
            return false
        }
        if lhs.startTimeoutMs != rhs.startTimeoutMs {
            return false
        }
        if lhs.connectTimeoutMs != rhs.connectTimeoutMs {
            return false
        }
        if lhs.deviceId != rhs.deviceId {
            return false
        }
        if lhs.deviceName != rhs.deviceName {
            return false
        }
        if lhs.sdk != rhs.sdk {
            return false
        }
        if lhs.app != rhs.app {
            return false
        }
        if lhs.network != rhs.network {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(publisherId)
        hasher.combine(gatewayAddresses)
        hasher.combine(caCertPath)
        hasher.combine(caCertPem)
        hasher.combine(startTimeoutMs)
        hasher.combine(connectTimeoutMs)
        hasher.combine(deviceId)
        hasher.combine(deviceName)
        hasher.combine(sdk)
        hasher.combine(app)
        hasher.combine(network)
    }
}


