                app: FfiConverterOptionString.read(from: &buf), 
                network: FfiConverterOptionString.read(from: &buf)
        )
    }

    public static func write(_ value: ProxyConfig, into buf: inout [UInt8]) {
        FfiConverterString.write(value.publisherId, into: &buf)
        FfiConverterSequenceString.write(value.gatewayAddresses, into: &buf)
        FfiConverterOptionString.write(value.caCertPath, into: &buf)
        FfiConverterOptionData.write(value.caCertPem, into: &buf)
