// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What the client is currently doing.
 */

public enum ClientState {
    
    case idle
    case connecting
    case connected
    case stopped
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientState: FfiConverterRustBuffer {
    typealias SwiftType = ClientState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .idle
        
        case 2: return .connecting
        
        case 3: return .connected
        
        case 4: return .stopped
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .idle:
            writeInt(&buf, Int32(1))
        
        
        case .connecting:
            writeInt(&buf, Int32(2))
        
        
        case .connected:
            writeInt(&buf, Int32(3))
        
        
        case .stopped:
            writeInt(&buf, Int32(4))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeClientState_lift(_ buf: RustBuffer) throws -> ClientState {
    return try FfiConverterTypeClientState.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeClientState_lower(_ value: ClientState) -> RustBuffer {
    return FfiConverterTypeClientState.lower(value)
}



extension ClientState: Equatable, Hashable {}




/**
 * The single error every fallible SDK call returns.
 *
 * The field is `reason`, not `message`, and that is not a style choice. uniffi
 * generates the Kotlin variant as a subclass of `kotlin.Exception` with an
 * `override val message`, so a field literally named `message` collides with
 * `Throwable.message` and the generated Kotlin does not compile. Upstream's
 * answer is to not name an error field `message`. Nothing else reads the name,
 * and Kotlin callers still get the text through `e.message` as usual.
 */
public enum ProxyError {

    
    
    case Failed(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeProxyError: FfiConverterRustBuffer {
    typealias SwiftType = ProxyError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ProxyError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ProxyError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


extension ProxyError: Equatable, Hashable {}

extension ProxyError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

